import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Video Generation Providers","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/providers/video.md","filePath":"integrations/providers/video.md","lastUpdated":1790952322000}'),r={name:"integrations/providers/video.md"};function i(s,e,n,l,c,p){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="video-generation-providers" tabindex="-1">Video Generation Providers <a class="header-anchor" href="#video-generation-providers" aria-label="Permalink to &quot;Video Generation Providers&quot;">​</a></h1><p>Memoh bots can generate videos through the <code>generate_video</code> tool. To enable it you need two things:</p><ol><li>A <strong>video provider</strong> with at least one video model, configured under <strong>Settings → Integrations → Video</strong>.</li><li>A <strong>Video Generation Model</strong> assigned to the bot under <strong>Bot Settings → Multimedia</strong>.</li></ol><p>If a bot has no video model assigned, the <code>generate_video</code> tool is not offered to it.</p><hr><h2 id="supported-providers" tabindex="-1">Supported Providers <a class="header-anchor" href="#supported-providers" aria-label="Permalink to &quot;Supported Providers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Client Type</th><th>Default Base URL</th></tr></thead><tbody><tr><td><strong>OpenRouter</strong></td><td><code>openrouter-video</code></td><td><code>https://openrouter.ai/api</code></td></tr><tr><td><strong>ModelArk (BytePlus)</strong></td><td><code>modelark-video</code></td><td><code>https://ark.ap-southeast.bytepluses.com/api/v3</code></td></tr><tr><td><strong>Volcengine (Ark)</strong></td><td><code>volcengine-video</code></td><td><code>https://ark.cn-beijing.volces.com/api/v3</code></td></tr></tbody></table><p>Each provider needs an <strong>API Key</strong>; <strong>Base URL</strong> is optional and falls back to the default above.</p><p>The bundled templates ship with current Seedance / Veo / Doubao-Seedance model presets:</p><ul><li><strong>OpenRouter</strong>: <code>bytedance/seedance-2.0</code>, <code>google/veo-3.1-fast</code>, <code>google/veo-3.1-lite</code></li><li><strong>ModelArk</strong>: <code>dreamina-seedance-2-0-260128</code>, <code>dreamina-seedance-2-0-fast-260128</code>, <code>dreamina-seedance-2-5</code></li><li><strong>Volcengine</strong>: <code>doubao-seedance-2-0-260128</code>, <code>doubao-seedance-2-0-fast-260128</code>, <code>doubao-seedance-2-5</code></li></ul><p>OpenRouter also supports <strong>Import Models</strong> from its live catalog. ModelArk and Volcengine do not expose a remote list, so their models come from the template or manual entry.</p><hr><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Open <strong>Settings → Integrations → Video</strong>.</li><li>Add a provider from the template list (OpenRouter, ModelArk, or Volcengine).</li><li>Fill in the API key, adjust the base URL only if you use a non-default endpoint, and save.</li><li>Check the <strong>Video Models</strong> section: import from the provider or add a model manually if the list is empty.</li><li>Open the bot&#39;s <strong>Settings → Multimedia</strong> and pick a <strong>Video Generation Model</strong>.</li></ol><hr><h2 id="how-the-bot-uses-it" tabindex="-1">How the Bot Uses It <a class="header-anchor" href="#how-the-bot-uses-it" aria-label="Permalink to &quot;How the Bot Uses It&quot;">​</a></h2><p>Ask the bot for a video in plain language. Under the hood:</p><ul><li><code>generate_video</code> starts a <strong>background task</strong> and returns immediately with a task ID; generation usually takes minutes, and the bot checks progress with its background-task tools.</li><li>The tool accepts a text <code>prompt</code> plus optional <code>duration_seconds</code>, <code>resolution</code> (such as <code>720p</code>/<code>1080p</code>), <code>aspect_ratio</code> (such as <code>16:9</code>, <code>9:16</code>, <code>1:1</code>), provider-specific <code>size</code>, and <code>generate_audio</code>.</li><li>The finished video is downloaded into the bot workspace under <code>/data/generated-videos/&lt;task_id&gt;.mp4</code> (<code>.webm</code>/<code>.mov</code> depending on the provider output).</li><li>The video is <strong>not sent anywhere automatically</strong> — the bot delivers it as a message attachment, and you can also grab it from the workspace <strong>Files</strong> tab.</li></ul><p>If the workspace is unreachable when generation finishes, the task still completes with a warning and the provider&#39;s output URL, but nothing is saved to disk.</p><hr><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./llm.html">Providers And Models</a></li><li><a href="./../../guides/container.html">Bot Workspace Management</a></li></ul>',22)])])}const u=o(r,[["render",i]]);export{g as __pageData,u as default};
